    // ONE call. No loop, and deliberately no `attempts` knob for anyone to raise.
    try {
      const res = await fetchImpl(endpoint.url, {
        method: 'POST',
        headers: {
          ...endpoint.headers,
          'content-type': 'application/json',
          authorization: `Bearer ${token}`,
          'user-agent': 'claudinite-executor',
