    return {
      open: real.map((i) => ({ number: i.number, title: i.title, updatedAt: i.updated_at, labels: (i.labels ?? []).map((l) => l.name ?? l) })),
      touched: real.filter((i) => new Date(i.updated_at) >= since).map((i) => i.number),
    };
  },

  // Every open branch, each with the date of its tip commit — so a precondition
  // can tell a branch that MOVED in the window from the standing pile that did
  // not. `touched` is the same field name, with the same meaning, the `prs` and
  // `issues` collectors carry; without it the branch dimension had no notion of
  // newness at all and every gate over it degenerated to "a branch exists".
  //
  // The tip date costs one commit read per DISTINCT tip sha (branches sharing a
  // tip share the read) because the branch listing carries no date of its own —
  // no REST listing does. That is the price of the only newness this dimension
  // can observe, and it is paid on a weekly clock over a handful of branches.
  // A tip read that fails leaves `updatedAt: null`, which is NOT touched: no
  // proof of movement never wakes an agent.
  async branches(gh, ctx) {
    const list = await paged(gh, `/repos/${ctx.repo}/branches`);
    const since = new Date(ctx.sinceIso);

    const dateBySha = new Map();
    for (const sha of new Set(list.map((b) => b.commit?.sha).filter(Boolean))) {
      const { status, json } = await gh(`/repos/${ctx.repo}/commits/${sha}`);
      const c = status === 200 ? json?.commit : null;
      dateBySha.set(sha, c?.committer?.date ?? c?.author?.date ?? null);
    }

    const entries = list.map((b) => ({ name: b.name, updatedAt: dateBySha.get(b.commit?.sha) ?? null }));
    return {
      names: entries.map((e) => e.name),
      list: entries,
      touched: entries.filter((e) => e.updatedAt && new Date(e.updatedAt) >= since).map((e) => e.name),
    };
  },

  async release(gh, ctx) {
    const { status, json } = await gh(`/repos/${ctx.repo}/releases/latest`);
    const latestTag = status === 200 ? (json?.tag_name ?? null) : null; // 404 → no release yet
    return { latestTag, manifestVersion: ctx.manifestVersion ?? null, shipsPipeline: ctx.shipsReleasePipeline ?? null };
  },

  // Whether the repo carries local packs, and whether a window commit touched
  // one (under either local root during the rename window).
  async localPacks(gh, ctx) {
    const commits = ctx.commits ?? await windowCommits(gh, ctx.repo, ctx.defaultBranch, ctx.sinceIso);
    const touches = (f) => LOCAL_PACK_ROOTS.some((r) => f.startsWith(r));
    const present = ctx.hasLocalPacks ?? null;
    return { present, changedInWindow: commits.some((c) => c.files.some(touches)) };
  },

  // Which DECLARED packs' vendored files changed in the window — the local echo
  // of "canon changed" (replaces the cross-repo relevantCanonChanged).
  async sharedMount(gh, ctx) {
    const commits = ctx.commits ?? await windowCommits(gh, ctx.repo, ctx.defaultBranch, ctx.sinceIso);
    const declared = new Set(ctx.activePacks ?? []);
    const changed = new Set();
    for (const c of commits) {
      for (const f of c.files) {
        const m = /^\.claudinite\/shared\/packs\/([^/]+)\//.exec(f);
        if (m && declared.has(m[1])) changed.add(m[1]);
      }
    }
    return { changedPacks: [...changed] };
  },

  // The conversation-logs orphan branch: present, and the age of its oldest JSONL
  // vs the configured retention (the age-based prune's trigger on quiet repos).
  //
  // Age comes from the FILENAME stamp, not from git/commit metadata. Commit dates
  // are the authoritative record of when a blob landed, but they are the wrong
  // authority here and cost more: (a) AGREEMENT — the consuming task's prune rule
  // is itself stated over the filename stamp ("each log whose filename stamp is
  // older than retention"), so a commit-date trigger would dispatch an agent over
  // logs the worker then declines to prune, and stay silent on ones it would
  // prune; (b) COST — one tree
  // read covers the whole branch, against one commit-history read per file, and
  // the branch accumulates one log per merged session. The name is machine-written
  // by the pack's capture step, never user input, so "trusting the name" is
  // trusting our own writer — and a drift guard pins the two formats together.
  async conversationLogs(gh, ctx) {
    const retentionDays = ctx.retentionDays ?? null;
    const branch = await gh(`/repos/${ctx.repo}/branches/conversation-logs`);
    if (branch.status !== 200) {
      return { present: false, retentionDays, oldestLogAgeDays: null, newestLogAgeDays: null, logCount: 0 };
    }

    // Logs sit flat at the branch root beside its README; a non-200 tree read (or
    // anything unparsable on it) is "no age to judge", never a failed collection.
    const { status, json } = await gh(`/repos/${ctx.repo}/git/trees/conversation-logs`);
    const stamps = (status === 200 && Array.isArray(json?.tree) ? json.tree : [])
      .map((e) => logStampMs(e?.path ?? ''))
      .filter((ms) => ms !== null);
    const now = new Date(ctx.now).getTime();
    const age = (ms) => (stamps.length && Number.isFinite(now) ? (now - ms) / 86400000 : null);
    // Both ends, because they answer opposite questions. The OLDEST drives the
    // age-based prune (is anything past retention). The NEWEST is the only NEWNESS
    // this dimension has: "did a session capture in the window", which is what a
    // precondition gated on repo movement needs and which a total count — true
    // forever once true — cannot say.
    return {
      present: true,
      retentionDays,
      oldestLogAgeDays: stamps.length ? age(Math.min(...stamps)) : null,
      newestLogAgeDays: stamps.length ? age(Math.max(...stamps)) : null,
      logCount: stamps.length,
    };
  },

  // WHAT THE MOUNT HOLDS, and whether it moved in this window: the installed engine
  // version, the installed pack versions, and whether any `.claudinite/shared/**`
  // file was touched by a commit in the window.
  //
  // `convergedInWindow` is what replaced the stamp's age (#1252). The age came off a
  // datetime that recorded the last FULL re-vendor rather than the last converge, so
  // it read months stale on a member converging nightly — and newness taken from the
  // objects' OWN movement in the window is where every other precondition here gets
  // it. `present` is the mount's existence, which the versions answer directly: an
  // engine that stamps always stamps.
  async stamp(gh, ctx) {
    const commits = ctx.commits ?? await windowCommits(gh, ctx.repo, ctx.defaultBranch, ctx.sinceIso);
    const convergedInWindow = commits.some((c) => c.files.some((f) => f.startsWith(`${SHARED_SUBDIR}/`)));
    return {
      present: (ctx.config?.engineVersion ?? null) !== null || Object.keys(ctx.config?.packVersions ?? {}).length > 0,
      engineVersion: ctx.config?.engineVersion ?? null,
      packVersions: ctx.config?.packVersions ?? {},
      convergedInWindow,
      canonHead: ctx.canonHead ?? null,
    };
  },

  // Fleet aggregate — canon-only, over the fleet PAT (DESIGN §3.3). A consumer
  // cannot declare it; the collector returns null unless the caller supplied a
  // fleet reader (wired on the canon and fleet-enforcer repos in Phase 2).
  // THE REQUEST READ (tasks-dispatch DESIGN §16.4). Unlike every collector beside
  // it, this one reads a single named object rather than a window: the issue THIS
  // item was created for, off `ctx.item.request`. That is what the precondition's
  // third argument buys — a verdict about one issue, which no window of repo
  // activity can single out.
  //
  // It reads facts and forms no judgment: who asked, who blessed it with the
  // approval phrase, and what PERMISSION each of them holds — never whether that is
  // enough. The rule lives in the task's precondition, where every other verdict is.
  //
  // Three shapes of answer, and the difference between the last two is the whole of
  // F27: `gone` (the API says it does not exist) is a fact a precondition can
  // decline on, while `unreadable` (a rate limit, a 500) is one it must NOT — a
  // decline's write-back cannot reach an issue it cannot read.
  async request(gh, ctx) {
    const number = ctx.item?.request ?? null;
    if (!number) return null;
    const { status, json } = await gh(`/repos/${ctx.repo}/issues/${number}`);
    if (status === 404 || status === 410) return { number, gone: true };
    if (status !== 200 || !json) return { number, unreadable: true, error: `the issues API answered ${status}` };

    // The permission API is the authority, never the payload's `author_association`:
    // `MEMBER` is any org member whatever their repo permission, and `COLLABORATOR`
    // includes read-only collaborators — both broader than push (F30). A read that
    // fails is unreadable, not "no permission": guessing downward here would refuse
    // a legitimate request over a rate limit.
    const permissions = new Map();
    let failed = null;
    const permissionOf = async (login) => {
      if (!login) return 'none';
      if (permissions.has(login)) return permissions.get(login);
      const res = await gh(`/repos/${ctx.repo}/collaborators/${encodeURIComponent(login)}/permission`);
      // A 403/404 here is a real answer: the caller may not read collaborators, or
      // this login is not one. The first is a repo-configuration fault and the
      // second is the ordinary "a stranger opened it" case, and only the API can
      // tell them apart — so a 404 is `none` and anything else stops the read.
      let value;
      if (res.status === 200) value = res.json?.role_name ?? res.json?.permission ?? 'none';
      else if (res.status === 404) value = 'none';
      else { failed = `the permission API answered ${res.status} for @${login}`; value = 'none'; }
      permissions.set(login, value);
      return value;
    };

    const author = json.user?.login ?? null;
    const authorPermission = await permissionOf(author);
    // The approval phrase is only worth a permission read on the comments that
    // carry it, so an issue with a long thread costs one read per distinct blesser.
    const comments = await paged(gh, `/repos/${ctx.repo}/issues/${number}/comments`);
    const approvals = [];
    for (const c of comments) {
      const login = c.user?.login ?? null;
      if (!login || !APPROVAL_RE.test(c.body ?? '')) continue;
      approvals.push({ login, permission: await permissionOf(login) });
    }
    if (failed) return { number, unreadable: true, error: failed };

    return {
      number,
      state: json.state,
      labels: (json.labels ?? []).map((l) => l.name ?? l),
      // STILL MARKED, in any spelling this repo's issues may carry: the origin the
      // one-issue model applies, and the two retired `claude-*` labels a shadow item's
      // issue wears. Withdrawing is removing what marked it, whichever that was.
      queued: (json.labels ?? []).map((l) => l.name ?? l)
        .some((l) => [ORIGIN_AD_HOC, QUEUED_LABEL, REQUEST_LABEL].includes(l)),
      author,
      authorPermission,
      approvals,
    };
  },

  async fleet(gh, ctx) {
    return ctx.fleet ?? null;
  },
};

export const SIGNAL_COLLECTORS = Object.keys(COLLECTORS);

// Collect exactly the requested signal names into one object. An unknown name is
// ignored (the task-declaration-shape check rejects those at author time); a
// collector that throws records `{ error }` under its key rather than sinking the
// whole collection (per-signal isolation).
export async function collectSignals(gh, ctx, names) {
  const out = {};
  // Commit-derived collectors share one window read.
  if (names.some((n) => ['commits', 'localPacks', 'sharedMount', 'stamp'].includes(n)) && !ctx.commits) {
    try { ctx = { ...ctx, commits: await windowCommits(gh, ctx.repo, ctx.defaultBranch, ctx.sinceIso) }; } catch { /* collectors re-read on demand */ }
  }
  for (const name of names) {
    const collect = COLLECTORS[name];
    if (!collect) continue;
    try { out[name] = await collect(gh, ctx); }
    catch (e) { out[name] = { error: e.message }; }
  }
  return out;
}

[Resource from github at repo://missingbulb/Claudinite/sha/3fd16f9d7fc5144bc6e39bdeedd27a2397cccf74/contents/packs/leaflet/worldRules/tile-attribution.mjs] import { finding } from '../../../engine/checks/helpers/findings.mjs';

// Converted from the leaflet prose: the tile provider's attribution is a LICENCE
// TERM, not decoration — an OSM-tiled map that ships without "© OpenStreetMap
// contributors" is using the tiles outside their terms. The prose names the exact
// failure mode: the attribution is dropped while *tidying the UI*, long after the
// map was wired, and nothing about the running map looks wrong afterwards. That
// makes it a static signature in the source — the `attribution` key on the
// `L.tileLayer(...)` options — so it converts.
//
// PARSED, NOT GREPPED (the skill's rule): `grep attribution` answers the wrong
// question — it is satisfied by the word appearing anywhere in the file, and it
// cannot tell WHICH tileLayer is missing it. So this reads each `L.tileLayer(`
// call site, walks its own argument list to the options object, and judges only
// that object's own top-level keys. Consequences, all deliberate:
//
//   - `L.tileLayer.wms(...)` is a different constructor and never matches.
//   - Options passed as a variable or built by a spread are NOT judged. The
//     literal is the only form where absence is provably absence; guessing at
//     the rest is how a check earns its false alarms.
//   - A file that calls `addAttribution` (Leaflet's documented out-of-band path —
//     `map.attributionControl.addAttribution(...)`) is skipped whole: there the
//     attribution legitimately lives away from the layer's options.
//   - Comments are blanked first, so prose that merely *names* the rule — this
//     header included, were it ever vendored as source — never fires it.
//
// Only the attribution half of the prose bullet converts. Its `maxZoom` sentence
// asks for the provider's REAL ceiling (19 for OSM), a per-provider value no
// check can judge, and Leaflet's own default is a legitimate answer for a map
// that never zooms that far — so that half stays prose.

const HTML = /\.html?$/i;
const SOURCE = /\.(html?|mjs|cjs|jsx?|tsx?)$/i;
const CALL = /\bL\.tileLayer\s*\(/g;
// The documented out-of-band path: attributionControl.addAttribution(...).
const OUT_OF_BAND = /\baddAttribution\s*\(/;

const blank = (s) => s.replace(/[^\n]/g, ' ');

// Length-preserving sibling of `stripComments`
// (engine/checks/helpers/code-scanning.mjs) — same string-aware state machine,
// but comment characters become spaces instead of vanishing. Offsets have to
// survive here because the scan reports a line number computed on the blanked
// text and, for HTML, splices script bodies back at their original positions.
function blankComments(source) {
  let out = '';
  let state = 'code'; // code | line | block | sq | dq | tpl
  for (let i = 0; i < source.length; i++) {
    const c = source[i];
    const c2 = source[i + 1];
    if (state === 'code') {
      if (c === '/' && c2 === '/') { state = 'line'; out += '  '; i++; continue; }
      if (c === '/' && c2 === '*') { state = 'block'; out += '  '; i++; continue; }
      if (c === "'") state = 'sq';
      else if (c === '"') state = 'dq';
      else if (c === '`') state = 'tpl';
      out += c;
    } else if (state === 'line') {
      if (c === '\n') { state = 'code'; out += c; } else out += ' ';
    } else if (state === 'block') {
      if (c === '*' && c2 === '/') { state = 'code'; out += '  '; i++; }
      else out += c === '\n' ? '\n' : ' ';
    } else {
      out += c;
      if (c === '\\') { out += c2 ?? ''; i++; }
      else if ((state === 'sq' && c === "'") || (state === 'dq' && c === '"') || (state === 'tpl' && c === '`')) {
        state = 'code';
      }
    }
  }
  return out;
}

// The file reduced to the JS the browser actually runs, everything else blanked
// to spaces so offsets (and therefore line numbers) are unchanged. For HTML that
// is the inline `<script>` bodies only — markup and page text are not code, and a
// Leaflet snippet quoted in a `<pre>` is not a call site.
function codeView(file, raw) {
  if (!HTML.test(file)) return blankComments(raw);
  const noComments = raw.replace(/<!--[\s\S]*?-->/g, blank);
  let out = blank(noComments);
  const re = /<script\b[^>]*>([\s\S]*?)<\/script\s*>/gi;
  for (let m = re.exec(noComments); m; m = re.exec(noComments)) {
    const open = noComments.indexOf('>', m.index);
    if (open === -1) continue;
    const start = open + 1;
    const body = blankComments(m[1]);
    out = out.slice(0, start) + body + out.slice(start + body.length);
  }
  return out;
}

const CLOSERS = { '(': ')', '[': ']', '{': '}' };

// From `src[open]` (an opening bracket), return the index of its match, or -1.
// String- and template-aware so a bracket inside a URL or a caption never
// unbalances the walk.
function matchBracket(src, open) {
  const stack = [CLOSERS[src[open]]];
  for (let i = open + 1; i < src.length; i++) {
    const c = src[i];
    if (c === '"' || c === "'" || c === '`') {
      for (i++; i < src.length; i++) {
        if (src[i] === '\\') i++;
        else if (src[i] === c) break;
      }
      continue;
    }
    if (CLOSERS[c]) stack.push(CLOSERS[c]);
    else if (c === ')' || c === ']' || c === '}') {
      if (stack[stack.length - 1] !== c) return -1;
      stack.pop();
      if (stack.length === 0) return i;
    }
  }
  return -1;
}

// Split `src[from..to)` on commas that sit at this level — nested calls, arrays,
// objects and string literals are stepped over whole.
function splitTopLevel(src, from, to) {
  const parts = [];
  let start = from;
  for (let i = from; i < to; i++) {
    const c = src[i];
    if (c === '"' || c === "'" || c === '`') {
      for (i++; i < to; i++) {
        if (src[i] === '\\') i++;
        else if (src[i] === c) break;
      }
      continue;
    }
    if (CLOSERS[c]) {
      const end = matchBracket(src, i);
      if (end === -1 || end >= to) return null;
      i = end;
      continue;
    }
    if (c === ',') { parts.push(src.slice(start, i)); start = i + 1; }
  }
  parts.push(src.slice(start, to));
  return parts;
}

const KEY = /^\s*(?:(['"])([A-Za-z_$][\w$]*)\1|([A-Za-z_$][\w$]*))\s*:/;

// The object literal's own top-level keys, or null when any member is a spread
// (`...defaults`) — a spread can carry `attribution` in, so the literal no longer
// proves its absence and the call is left alone.
function topLevelKeys(src, open) {
  const close = matchBracket(src, open);
  if (close === -1) return null;
  const members = splitTopLevel(src, open + 1, close);
  if (members === null) return null;
  const keys = [];
  for (const member of members) {
    if (member.trim() === '') continue;
    if (member.trim().startsWith('...')) return null;
    const m = KEY.exec(member);
    if (!m) continue;
    keys.push(m[2] ?? m[3]);
  }
  return keys;
}

const rule = {
  id: 'leaflet/tile-attribution',
  severity: 'blocking',
  description: 'An L.tileLayer(...) built with a literal options object carries the tile provider\'s attribution',
  doc: 'packs/leaflet/RULES.md',
  why: 'the provider\'s attribution is a licence term, not decoration — an unattributed tile layer uses the tiles outside their terms, and nothing about the running map looks wrong, so a UI tidy-up drops it and no one notices',

  run(ctx) {
    const out = [];
    for (const file of ctx.files) {
      if (!SOURCE.test(file)) continue;
      const raw = ctx.read(file);
      if (raw === null || !raw.includes('L.tileLayer')) continue;
      const src = codeView(file, raw);
      if (OUT_OF_BAND.test(src)) continue;

      CALL.lastIndex = 0;
      for (let m = CALL.exec(src); m; m = CALL.exec(src)) {
        const open = m.index + m[0].length - 1;
        const close = matchBracket(src, open);
        if (close === -1) continue;
        const args = splitTopLevel(src, open + 1, close);
        if (args === null) continue;

        const options = (args[1] ?? '').trim();
        if (args.length > 1) {
          // Not a literal — options come from a variable, a call, or a spread we
          // cannot see into. Absence here is not provable, so it is not judged.
          if (!options.startsWith('{')) continue;
          // Where args[1]'s own text begins in `src`, past its leading blanks.
          const objStart = open + 1 + args[0].length + 1
            + (args[1].length - args[1].trimStart().length);
          const keys = topLevelKeys(src, objStart);
          if (keys === null || keys.includes('attribution')) continue;
        }

        out.push(finding(rule, {
          file,
          line: src.slice(0, m.index).split('\n').length,
          what: args.length > 1
            ? 'builds an L.tileLayer with a literal options object that has no `attribution`'
            : 'builds an L.tileLayer with no options at all, so no `attribution`',
          fix: 'add attribution to this layer\'s options — e.g. attribution: \'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors\' — or, where the credit is genuinely supplied elsewhere, register it through map.attributionControl.addAttribution(...)',
        }));
      }
    }
    return out;
  },
};

export default rule;

